301			{ID: "already-defect", Kind: "static", Severity: "high", Invariant: "broken"},
302			{ID: "needs-bytecode", Kind: "symbolic", Severity: "critical", Invariant: "other"},
303		}
304		artifact := Artifact{Name: "Vault", ABI: "abi", Bytecode: "", Source: "Vault.sol"}
305		findings, err := Run(artifact, rules, map[string]bool{"broken": false, "other": false})
306		if err == nil {
307			t.Fatal("the audit must fail when a symbolic rule lacks bytecode")
308		}
309		if !strings.Contains(err.Error(), "needs-bytecode") {
310			t.Fatalf("error must name the rule missing content: %v", err)
311		}
312		if findings != nil {
313			t.Fatalf("no partial findings may be returned on failure, got %+v", findings)
314		}
315	}
316	
317	// 为规则补齐所需内容后，相同布尔值应恢复正常结论；先前的输入不足绝不能被
318	// 记作合约缺陷。
319	func TestRunRecoversAfterSupplyingRequiredContent(t *testing.T) {
320		rules := []Rule{
321			{ID: "abi-rule", Kind: "static", Severity: "high", Invariant: "inv-a", RequiresABI: true},
322			{ID: "sym-rule", Kind: "symbolic", Severity: "critical", Invariant: "inv-b"},
323		}
324		invariants := map[string]bool{"inv-a": false, "inv-b": false}
325	
326		incomplete := Artifact{Name: "Vault", ABI: "", Bytecode: "", Source: "Vault.sol"}
327		if findings, err := Run(incomplete, rules, invariants); err == nil {
328			t.Fatalf("empty ABI and bytecode must fail, got findings %+v", findings)
329		}
330	
331		complete := Artifact{Name: "Vault", ABI: `[{"name":"withdraw"}]`, Bytecode: "0x6080", Source: "Vault.sol"}
332		findings, err := Run(complete, rules, invariants)
333		if err != nil {
334			t.Fatalf("with the required content supplied the same booleans must audit: %v", err)
335		}
336		if len(findings) != 2 {
337			t.Fatalf("findings = %d, want 2 real defects after content is supplied", len(findings))
338		}
339		set := findingSet(findings)
340		for _, want := range []findingKey{
341			{"abi-rule", "high", "inv-a", "invariant inv-a does not hold"},
342			{"sym-rule", "critical", "inv-b", "invariant inv-b does not hold"},
343		} {
344			if set[want] != 1 {
345				t.Errorf("missing expected finding %+v; got %+v", want, findings)
346			}
347		}
348	}
349	
350	// 产物名为必填输入；空名字是输入错误且不返回任何发现。
351	func TestRunRequiresArtifactName(t *testing.T) {
352		rules := []Rule{{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv"}}
353		findings, err := Run(Artifact{ABI: "abi", Bytecode: "0x1"}, rules, map[string]bool{"inv": false})
354		if err == nil {
355			t.Fatal("an empty artifact name must be an input error")
356		}
357		var ei errInvalid
358		if !errors.As(err, &ei) {
359			t.Fatalf("expected errInvalid, got %T: %v", err, err)
360		}
361		if findings != nil {
362			t.Fatalf("failure must return no findings, got %+v", findings)
363		}
364	}
365	
366	// 对于规则版本完整的同一份有效输入，两种调用方式的缺陷归属（规则、严重
367	// 级别、不变式名）与证据必须一致；报告中的每条 finding 还应绑定本次产物
368	// 哈希和对应规则版本。报告路径上，true 是“通过”、未提供是“未检查”，
369	// 两者不能因为都没有 finding 而混为一种结论。
370	func TestRunParityWithReportFindings(t *testing.T) {
371		rules := []Rule{
372			{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.0.0"},
373			{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true, Version: "2.1.0"},
374			{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic", Version: "0.9.0"},
375			{ID: "shared-a", Kind: "static", Severity: "high", Invariant: "shared", Version: "3.0.0"},
376			{ID: "shared-b", Kind: "static", Severity: "low", Invariant: "shared", Version: "3.0.0"},
377			{ID: "passing", Kind: "static", Severity: "low", Invariant: "holds-explicitly", Version: "4.0.0"},
378			{ID: "never-checked", Kind: "static", Severity: "low", Invariant: "no-value-given", Version: "5.0.0"},
379		}
380		invariants := map[string]bool{
381			"no-reentrant-withdraw": false, // defect
382			"owner-only-withdraw":   true,  // pass
383			"balance-monotonic":     false, // defect
384			"shared":                false, // two defects, one per rule
385			"holds-explicitly":      true,  // pass
386			"orphan-false":          false, // referenced by nobody: no finding either way
387		}
388		artifact := sampleArtifact()
389	
390		listFindings, err := Run(artifact, rules, invariants)
391		if err != nil {
392			t.Fatal(err)
393		}
394		report, err := BuildReport(artifact, rules, invariants, nil)
395		if err != nil {
396			t.Fatal(err)
397		}
398	
399		// “通过”与“未检查”在报告中分别显示，不能合并。
400		statusByID := map[string]string{}
401		for _, r := range report.Rules {
402			statusByID[r.ID] = r.Status
403		}
404		if statusByID["passing"] != StatusPass {
405			t.Errorf("passing = %q, want %q", statusByID["passing"], StatusPass)
406		}
407		if statusByID["never-checked"] != StatusUnchecked {
408			t.Errorf("never-checked = %q, want %q", statusByID["never-checked"], StatusUnchecked)
409		}
410		if statusByID["access-control"] != StatusPass {
411			t.Errorf("access-control = %q, want %q", statusByID["access-control"], StatusPass)
412		}
413	
414		// 缺陷集合一致：归属与证据逐条相同（顺序可能不同，按集合比较）。
415		listSet := findingSet(listFindings)
416		reportSet := make(map[findingKey]int, len(report.Findings))
417		hash := ArtifactHash(artifact)
418		versionByID := make(map[string]string, len(rules))
419		for _, r := range rules {
420			versionByID[r.ID] = r.Version
421		}
422		for _, f := range report.Findings {
423			reportSet[findingKey{f.RuleID, f.Severity, f.Invariant, f.Evidence}]++
424			// 每条报告 finding 绑定本次产物哈希与对应规则版本。
425			if f.ArtifactHash != hash {
426				t.Errorf("finding %s artifact hash = %q, want %q", f.RuleID, f.ArtifactHash, hash)
427			}
428			if f.Version == "" {
429				t.Errorf("finding %s must bind the rule version", f.RuleID)
430			} else if f.Version != versionByID[f.RuleID] {
431				t.Errorf("finding %s version = %q, want %q", f.RuleID, f.Version, versionByID[f.RuleID])
432			}
433		}
434		if len(listSet) != len(reportSet) {
435			t.Fatalf("Run gives %d distinct findings, report gives %d:\nlist=%+v\nreport=%+v",
436				len(listSet), len(reportSet), listFindings, report.Findings)
437		}
438		for key, n := range listSet {
439			if reportSet[key] != n {
440				t.Errorf("finding %+v count = %d from Run but %d from report", key, n, reportSet[key])
441			}
442		}
443		for key, n := range reportSet {
444			if listSet[key] != n {
445				t.Errorf("finding %+v count = %d from report but %d from Run", key, n, listSet[key])
446			}
447		}
448	
449		// 具体期望：4 条缺陷，包括共享同一 false 不变式的两条规则。
450		wantKeys := map[findingKey]bool{
451			{"reentrancy-guard", "high", "no-reentrant-withdraw", "invariant no-reentrant-withdraw does not hold"}: true,
452			{"invariant-preserved", "critical", "balance-monotonic", "invariant balance-monotonic does not hold"}:  true,
453			{"shared-a", "high", "shared", "invariant shared does not hold"}:                                       true,
454			{"shared-b", "low", "shared", "invariant shared does not hold"}:                                        true,
455		}
456		if len(listFindings) != len(wantKeys) {
457			t.Fatalf("expected %d defects, got %d: %+v", len(wantKeys), len(listFindings), listFindings)
458		}
459		for key := range listSet {
460			if !wantKeys[key] {
461				t.Errorf("unexpected defect %+v", key)
462			}
463		}
464	}
465	
466	// 把不变式值翻转后，两种调用方式应同步地从“有缺陷”变为“无缺陷”。
467	func TestRunParityWithReportWhenInvariantHolds(t *testing.T) {
468		rules := []Rule{
469			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1"},
470			{ID: "r2", Kind: "symbolic", Severity: "low", Invariant: "inv", Version: "2"},
471		}
472		artifact := sampleArtifact()
473		listFindings, err := Run(artifact, rules, map[string]bool{"inv": true})
474		if err != nil {
475			t.Fatal(err)
476		}
477		report, err := BuildReport(artifact, rules, map[string]bool{"inv": true}, nil)
478		if err != nil {
479			t.Fatal(err)
480		}
481		if len(listFindings) != 0 || len(report.Findings) != 0 {
482			t.Fatalf("true invariant must give no findings on either path: %+v %+v",
483				listFindings, report.Findings)
484		}
485	}
