    status = check.Status
    note = check.Note
} else {
    switch checkInvariant(rule, invariants) {
    case invariantHolds:
        status = StatusPass
    case invariantViolated:
        status = StatusDefect
    }
}
...
if status == StatusDefect {
    evidence := note
    if evidence == "" {
        evidence = invariantEvidence(rule.Invariant)
    }
    ...
}
```

validateReport:

```go
wantEvidence := rule.Note
if wantEvidence == "" {
    wantEvidence = invariantEvidence(rule.Invariant)
}
```

